import { createHash } from "node:crypto";

const HIBP_RANGE_URL = "https://api.pwnedpasswords.com/range/";

export type BreachResult =
  | { status: "breached"; count: number }
  | { status: "clean" }
  | { status: "unknown" }; // API failed or timed out

export async function checkBreachedPassword(
  password: string,
  opts: { timeoutMs?: number; minCount?: number } = {}
): Promise<BreachResult> {
  const { timeoutMs = 1500, minCount = 1 } = opts;

  const sha1 = createHash("sha1").update(password, "utf8").digest("hex").toUpperCase();
  const prefix = sha1.slice(0, 5);   // only this leaves your system
  const suffix = sha1.slice(5);

  try {
    const res = await fetch(HIBP_RANGE_URL + prefix, {
      headers: { "Add-Padding": "true", "User-Agent": "YourApp-breach-check" },
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) return { status: "unknown" };

    const body = await res.text();
    for (const line of body.split("\n")) {
      const [hashSuffix, countStr] = line.trim().split(":");
      if (hashSuffix === suffix) {
        const count = parseInt(countStr, 10);
        // Padded decoy entries have count 0; ignore them
        if (count >= minCount) return { status: "breached", count };
      }
    }
    return { status: "clean" };
  } catch {
    return { status: "unknown" };
  }
}
```

